import { CoreBehavior } from "../../common/game-core";
import { gameStateStore, ISettingsState } from "../../logic";

/**
 *  Включает и выключает звуки по стейту настроек
 *  следит за состоянием
 **/
export class SoundSettingsBehavior extends CoreBehavior {
  readonly type = "SoundSettingsBehavior";

  create(scene: Phaser.Scene) {
    const settings = gameStateStore.getStateConnector("settings");

    const applySound = (state: ISettingsState) => {
      scene.sound.mute = !state.isSoundOn;
    };

    applySound(settings.getState());
    this.addUnSub(settings.on(applySound));
  }
}
