import { AlignMethod, layoutColumn, layoutRow } from "@kvisaz/phaser-sugar";
import { CleanableSceneView } from "../../common/scenes";
import { getCurrentLocale, ViewElementBuilder } from "../../assets";
import {
  centeredCardLayoutStrategy, ClassicCardData,
  IKlondikeExposedLiveState,
  klondikeGraveLayoutStrategy,
  KlondikeView,
  makeArray,
  showValueCardFromTopLayoutStrategy,
  State, StateConnector
} from "../../common";
import { GameEvents, gameStateStore, IGameSessionState, IPlayerGoodyState } from "../../logic";
import { mapKlondike2Game } from "./mapKlondike2Game";
import { ConsumableButton } from "../../assets/builders/ViewElementBuilder/components/ConsumableButton";
import { CenteredContainerButton } from "../../common/game-core";

/**
 * Отдельный компонент для сцены позволяет  тестировать
 * - его работу и отключение в песочнице
 *
 * Вызывать только в create
 * автоматически отписывается
 * **/
export class GameSceneView extends CleanableSceneView {
  private klondikeView: KlondikeView | undefined;
  private gameEvents: GameEvents | undefined;
  private buttonUndo: ConsumableButton | undefined;
  private buttonNewGame: CenteredContainerButton | undefined;
  private buttonHint: ConsumableButton | undefined;
  private buttonVision: ConsumableButton | undefined;
  private buttonMagic: ConsumableButton | undefined;
  private buttonReplay: CenteredContainerButton | undefined;

  private gameSession: StateConnector<IGameSessionState> | undefined;

  private get locale() {
    return getCurrentLocale();
  }

  private _builder: ViewElementBuilder | undefined;
  private get builder() {
    if (this._builder == null) this._builder = new ViewElementBuilder(this.scene);
    return this._builder;
  }

  private clearBuilder() {
    this._builder = undefined;
  }

  create() {
    console.log("create GameSceneView!!");
    const { scene, builder } = this;
    this.gameSession = gameStateStore.getStateConnector("gameSession");
    this.addUnSub(() => this.gameSession?.unSubScribeAll());
    this.addUnSub(() => this.clearBuilder());

    this.gameEvents = new GameEvents(scene);
    this.addUnSub(() => {
      this.gameEvents?.unSubscribeAll();
      this.gameEvents = undefined;
    });

    const bg = builder.backgroundGameScene();
    this.addUnSub(bg);
    this.createUi();

    this.gameEvents.on("gameViewStartKlondike", data => {
      this.runKlondike(data);
    });

    const consumables = gameStateStore.getStateConnector("playerGoodyState");
    this.addUnSub(() => consumables.unSubScribeAll());
    const applyConsumables = (state: IPlayerGoodyState) => {
      this.buttonUndo?.setAmount(state.undoAmount);
      this.buttonMagic?.setAmount(state.magicAmount);
      this.buttonVision?.setAmount(state.visionAmount);
      this.buttonHint?.setAmount(state.hintAmount);
    };
    applyConsumables(consumables.getState());
    consumables.on(applyConsumables);
  }

  private runKlondike(args: { cards: ClassicCardData[] }) {
    this.klondikeView?.destroy();
    this.klondikeView = this.createKlondikeView(args.cards);
    this.subscribeKlondikeLiveState(this.klondikeView.liveState);
    if (this.klondikeView) {
      const unSub = mapKlondike2Game(this.scene, this.klondikeView.events);
      this.addUnSub(unSub);
    }
  }

  private createCardPlaces() {
    const { scene, align, builder } = this;
    console.log("createCardPlaces!!!");
    const cardPlaces = {
      deck: builder.cardPlace(),
      grave: builder.cardPlace(),
      bases: makeArray(4).map((i) => builder.cardPlace(true)),
      piles: makeArray(7).map((i) => builder.cardPlace())
    };

    const cardTopPadding = 32;
    const cardGap = 32;

    const deckRow = layoutRow({
      children: [cardPlaces.deck, cardPlaces.grave],
      nextOffsetX: cardGap
    });

    const pilesRow = layoutRow({
      children: [...cardPlaces.piles],
      nextOffsetX: cardGap
    });

    const basesRow = layoutRow({
      children: [...cardPlaces.bases],
      nextOffsetX: cardGap
    });

    align.anchorSceneScreen(scene).topIn(deckRow, cardTopPadding).leftIn(deckRow, 338);
    align
      .anchor(deckRow)
      .bottomTo(pilesRow, cardGap * 2)
      .leftIn(pilesRow);
    align.anchor(deckRow).topIn(basesRow);
    align.anchor(pilesRow).rightIn(basesRow);

    return cardPlaces;
  }

  private createKlondikeView(cards: ClassicCardData[]) {
    const { scene, builder, locale } = this;
    const klondikeView = new KlondikeView({
      scene,
      locale,
      initCards: cards,
      cardPlaces: this.createCardPlaces(),
      builders: {
        cardBack: () => builder.cardBack(),
        cardFace: (suit, value) => builder.cardFace(suit, value)
      },
      cardLayout: {
        deck: centeredCardLayoutStrategy,
        grave: klondikeGraveLayoutStrategy,
        base: centeredCardLayoutStrategy,
        pile: (cards, inputZone) =>
          showValueCardFromTopLayoutStrategy(cards, inputZone, { offsetY: 32 })
      }
    });
    this.addUnSub(klondikeView);

    return klondikeView;
  }

  private subscribeKlondikeLiveState(liveState: State<IKlondikeExposedLiveState>) {
    const applyLiveState = (state?: IKlondikeExposedLiveState) => {
      if (state == null) return;
      this.buttonUndo?.enable(state.isHistory === true);
      this.buttonHint?.enable(state.hintCard != null);
      this.buttonVision?.enable(state.isVisionPossible === true);
      this.buttonMagic?.enable(state.magicCombo != null);
    };

    liveState.on(applyLiveState);
    applyLiveState(liveState.getState());
  }

  private createUi() {
    const { scene, builder, align, klondikeView, gameEvents } = this;
    const padding = 16;

    const buttonSettings = builder.buttonSettings(() => {
      this.gameEvents?.emit("settingsDialogRequested");
    });
    align.anchorSceneScreen(scene).topIn(buttonSettings, padding).rightIn(buttonSettings, -padding);
    this.addUnSub(buttonSettings);
    console.log("todo - settings dialog");

    const scoreInfo = builder.gameInfoScoreTable(0);
    this.addUnSub(scoreInfo);
    align.anchorSceneScreen(scene).leftIn(scoreInfo, padding).topIn(scoreInfo, padding);
    this.gameSession?.on(state => scoreInfo.setScore(state.score), 'score');

    const timeInfo = builder.gameInfoTimeTable(0);
    this.addUnSub(timeInfo);
    align.anchor(scoreInfo).leftIn(timeInfo).bottomTo(timeInfo, padding);
    this.gameSession?.on(state => timeInfo.setTime(state.timeMs), 'timeMs');

    this.buttonNewGame = builder.buttonNewGame(() => {
      this.gameEvents?.emit("onNewGameButtonClick");
    });
    this.buttonUndo = builder.buttonUndo(() => {
      this.gameEvents?.emit("onUndoButtonClick");
    });
    this.buttonHint = builder.buttonHint(() => {
      this.gameEvents?.emit("onHintButtonClick");
    });
    this.buttonVision = builder.buttonVision(() => {
      this.gameEvents?.emit("onVisionButtonClick");
    });
    this.buttonMagic = builder.buttonMagic(() => {
      this.gameEvents?.emit("onMagicButtonClick");
    });
    this.buttonReplay = builder.buttonReplayGame(() => {
      this.gameEvents?.emit("onReplayGameButtonClick");
    });

    const gameIconButtons = [
      this.buttonNewGame,
      this.buttonUndo,
      this.buttonHint,
      this.buttonVision,
      this.buttonMagic,
      this.buttonReplay
    ];
    this.addUnSub(gameIconButtons);

    const sidebar = layoutColumn({
      children: [...gameIconButtons],
      nextOffsetY: padding,
      alignToAnchor: AlignMethod.LEFT_IN
    });

    align
      .anchor(timeInfo)
      .bottomTo(sidebar, padding * 2)
      .leftIn(sidebar);
  }
}
