import { Align } from "@kvisaz/phaser-sugar";
import { setLocaleFromString, SoundType, ViewElementBuilder } from "../../assets";
import { GameEvents } from "../../logic";
import { Scenes } from "../../common/game-core";

interface IProps {
  scene: Phaser.Scene;
}

export class StartView {
  constructor(private props: IProps) {
    const { scene } = this.props;
    const align = new Align();
    const builder = new ViewElementBuilder(scene);
    builder.backgroundStartScene();

    const gameEvents = new GameEvents(scene);

    const padding = 16;
    align.anchorSceneScreen(scene);
    setLocaleFromString('en');

    const titleDecoration = builder.textStartScreenTitle();
    align.center(titleDecoration).topIn(titleDecoration, padding);
    titleDecoration.setInteractive({
      useHandCursor: true
    }).on(Phaser.Input.Events.GAMEOBJECT_POINTER_DOWN, () => {
      builder.sound(SoundType.click)
    });

    const logo = builder.startScreenLogo();
    align.anchor(titleDecoration).centerX(logo).bottomTo(logo, padding);

    const buttonSettings = builder.buttonSettings(()=>{
      gameEvents.emit('settingsDialogRequested');
    });
    align.anchorSceneScreen(scene).topIn(buttonSettings, padding).rightIn(buttonSettings, -padding);

    const startButton = builder.buttonStart(()=>{
      scene.scene.start(Scenes.Game);
    });
    align.anchorSceneScreen(scene).center(startButton).bottomIn(startButton, -padding);
  }

}
