import { CardSuit, CardValue } from "../cards-classic";
import { IKlondikeCard, IKlondikeStack, IKlondikeStackMap, IMagicCombo, KlondikeStackType } from "./interfaces";

export class KlondikeSolitaireRules {
  public readonly BASE_AMOUNT = 4;
  public readonly PILES_AMOUNT = 7;

  private readonly valueOrder: CardValue[] = [
    "ace",
    2,
    3,
    4,
    5,
    6,
    7,
    8,
    9,
    10,
    "jack",
    "queen",
    "king",
  ];

  constructor() {}

  /** карту можно двигать **/
  public isCardMovable(card: IKlondikeCard, stackMap: IKlondikeStackMap): boolean {
    const stack = stackMap.get(card.stackId);
    if (stack == null) {
      console.warn("stack==null", card.suit, card.value);
      return false;
    }
    // не можем двигать не перевернутые
    if (!card.isFaceUp) return false;
    // верхнюю всегда можно двигать
    if (stack.topCard === card) return true;

    // или это карта в рабочей стопке Pile (to do = проверить на то что можно двигать стопку)
    return stack.type === KlondikeStackType.PILE;
  }

  /** получить карты, которые допустимо перетаскивать стопкой при клике на карте (только для PILE) */
  public getPileMovableCards(card: IKlondikeCard, stackMap: IKlondikeStackMap): IKlondikeCard[] {
    const stack = stackMap.get(card.stackId);

    // 1) запрет на другой тип стопки и проверка нулевой длины
    if (stack == null || stack.type !== KlondikeStackType.PILE || stack.cards.length === 0)
      return [];

    // 2) По правилам Косынки перетаскивать можно только открытую карту (и открытую цепочку над ней)
    if (!card.isFaceUp) return [];

    // 3) Если это верхняя карта стопки и она открыта — можно двигать её одну
    const isTop = card === stack.topCard;
    if (isTop) return [card];

    // 5) Проверяем всю последовательность от touched до вершины стопки:
    //    - все карты должны быть открыты
    //    - каждая верхняя карта должна «цепляться» к нижней по правилу PILE
    //    cardPile упорядочен снизу-вверх, значит пары (нижняя, верхняя) идут как (i, i+1)
    const { cards } = stack;
    const startIndex = cards.indexOf(card);
    for (let i = startIndex; i < stack.cards.length - 1; i++) {
      const lowerCard = cards[i];
      const upperCard = cards[i + 1];

      // 5.1) Любая закрытая карта внутри цепочки делает перенос недопустимым
      if (!lowerCard.isFaceUp || !upperCard.isFaceUp) return [];

      // 5.2) Проверяем «чередование цвета» и «строго на 1 меньше» для верхней относительно нижней
      //      Внутри стопки: order(upper) = order(lower) - 1 и цвет противоположный
      //      Наша isPileChainable ожидает (top=верхняя, bottom=нижняя)
      if (!lowerCard || !upperCard || !this.isPileChainable(upperCard, lowerCard)) return [];
    }

    // 6) Если все пары валидны и все карты открыты — можно переносить всю верхнюю часть стопки
    return cards.slice(startIndex);
  }

  /**
   * Ищет в рабочих стопках верхнюю закрытую карту, которую можно немедленно пристроить.
   *
   * Алгоритм:
   * - для каждой стопки pile берёт ближайшую к верху карту со стороны рубашки;
   * - проверяет возможность отправить её в любую базу через `canMoveToBase`;
   * - если базы не подходят, ищет перенос в другие pile через `canMoveToPile`.
   * Возвращает первое найденное совпадение.
   *
   * @param stackMap полная коллекция стопок, включая piles и bases
   * @returns IMagicCombo | undefined описание найденного хода или `undefined`, если подходящих закрытых карт нет
   */
  public getPilesHiddenGoodCard(stackMap: IKlondikeStackMap): IMagicCombo | undefined {
    for (const fromPile of stackMap.piles) {
      const hiddenCard = [...fromPile.cards].reverse().find((card) => !card.isFaceUp);
      if (!hiddenCard) continue;

      const toBase = stackMap.bases.find((base) => this.canMoveToBase(hiddenCard, base));
      if (toBase) {
        return { card: hiddenCard, fromPile, toStack: toBase };
      }

      const toPile = stackMap.piles.find(
        (targetPile) => targetPile !== fromPile && this.canMoveToPile(hiddenCard, targetPile),
      );
      if (toPile) {
        return { card: hiddenCard, fromPile, toStack: toPile };
      }
    }
  }

  /** можно положить в базу сборки **/
  public canMoveToBase(card: IKlondikeCard, base: IKlondikeStack): boolean {
    // пустая база - можем положить туза
    if (base.topCard == null) return card.value === "ace";
    // или их можно соединить
    return this.isBaseChainable(card, base.topCard);
  }

  public isDroppable(card: IKlondikeCard | undefined, dropZone: IKlondikeStack): boolean {
    // не карта
    if (card == null) return false;

    // на колоду не можем бросить никогда
    if (dropZone.type === KlondikeStackType.DECK) {
      return false;
    }

    // на сброс не можем бросить никогда
    if (dropZone.type === KlondikeStackType.GRAVE) {
      return true;
    }

    if (dropZone.type === KlondikeStackType.BASE) {
      return this.canMoveToBase(card, dropZone);
    }

    if (dropZone.type === KlondikeStackType.PILE) {
      return this.canMoveToPile(card, dropZone);
    }

    return false;
  }

  /** можно положить в рабочую стопку для тасовки **/
  public canMoveToPile(movingCard: IKlondikeCard, pile: IKlondikeStack): boolean {
    // ничего нет - можем класть только короля
    if (pile.topCard == null) {
      return movingCard.value === "king";
    }

    // можем положить только карты другого цвета и значение меньше на 1
    return this.isPileChainable(movingCard, pile.topCard);
  }

  // cочетаются ли карты в рабочей стопке - не проверяй стопку
  public isPileChainable(top: IKlondikeCard, bottom: IKlondikeCard): boolean {
    return (
      !this.isSameColor(top.suit, bottom.suit) &&
      this.cardOrder(bottom.value) === this.cardOrder(top.value) + 1
    );
  }

  // cочетаются ли карты в базе - не проверяй стопку
  public isBaseChainable(top: IKlondikeCard, bottom: IKlondikeCard): boolean {
    return (
      top.suit === bottom.suit && this.cardOrder(bottom.value) === this.cardOrder(top.value) - 1
    );
  }

  private cardOrder(value: CardValue): number {
    return this.valueOrder.indexOf(value);
  }

  private isRed(suit: CardSuit): boolean {
    return suit === CardSuit.heart || suit === CardSuit.diamond;
  }

  private isSameColor(suit1: CardSuit, suit2: CardSuit): boolean {
    return this.isRed(suit1) === this.isRed(suit2);
  }
}
