import { KlondikeStackType } from "./interfaces";
import { CardSuit, CardValue } from "../cards-classic";
import { TypedEventsEmitter } from "../../events";

export interface IKlondikeEvents {
  /** окончание раздачи **/
  onDealFinish: void;
  showHint: void;

  /** показать все карты в стопках **/
  doVision: { durationMs: number };
  /** вытащить и применить карту если есть **/
  doMagic: { durationMs: number };
  visionStart: void;
  visionEnd: void;


  undoCardMove: void;
  undoCardMoveFinished: void;
  hintShown: {
    suit: CardSuit;
    value: CardValue;
    fromStack: { type: KlondikeStackType; id: string };
  };
  hintShownFail: void;
  cardMove: {
    suit: CardSuit;
    value: CardValue;
    fromStack: { type: KlondikeStackType; id: string };
    toStack: { type: KlondikeStackType; id: string };
  };
  cardSound: void,
  cardAutoMoveFail: {
    suit: CardSuit;
    value: CardValue;
    fromStack: { type: KlondikeStackType; id: string };
  }
}

export class KlondikeEventsEmitter extends TypedEventsEmitter<IKlondikeEvents>{}
