import { CardSide, IAbstractCard, ICardStack } from "../cards-abstract";
import { CardSuit, CardValue } from "../cards-classic";

export enum KlondikeStackType {
  DECK = "deck",
  GRAVE = "grave",
  BASE = "base",
  PILE = "pile",
}

export enum KlondikeLiveStep {
  /** дефолтное состояния **/
  init = "init",
  /** ждем ввод юзера, готовы к нему **/
  userWaiting = "userWaiting",
  /** юзер драггинг **/
  userDragging = "userInput",
  /** включилась анимация **/
  animation = "animation",
}

export interface IKlondikeStack extends ICardStack<IKlondikeCard> {
  type: KlondikeStackType;
}

export interface IKlondikeCard extends IAbstractCard {
  flip(to?: CardSide): void;

  type: string;
  value: CardValue;
  suit: CardSuit;
  isFaceUp: boolean;
}

type KlondikeStackId = string;

export interface IKlondikeStackMap extends Map<KlondikeStackId, IKlondikeStack> {
  deck: IKlondikeStack;
  grave: IKlondikeStack;
  bases: IKlondikeStack[];
  piles: IKlondikeStack[];
}

export interface IMagicCombo {
  card: IKlondikeCard;
  fromPile: IKlondikeStack;
  toStack: IKlondikeStack;
}

/** состояние клондайка за которым могут наблюдать внешние **/
export interface IKlondikeExposedLiveState {
  /**
   * Существующая хорошая карта для подсказки
   * **/
  hintCard?: IKlondikeCard;
  /**
   * Есть ли в piles закрытые карты
   **/
  isVisionPossible?: boolean;
  /**
   * Есть ли в истории ходы (годится для undo)
   **/
  isHistory?: boolean;
  /**
   * карта, которая закрыта но лежит в fromPile
   * и которая может образовать комбо с одной из pile
   * или лечь в base
   */
  magicCombo?: IMagicCombo;

  /**
   * Доступно ли автозавершение
   * - то есть открыты ли все карты (isFaceUp)
   * - И могут ли они уйти на базы
   **/
  isAutoFinishPossible?: boolean;
  /**
   * Текущая стадия — ожидание ввода или анимации
   */
  step: KlondikeLiveStep;
}
