import { Align } from "@kvisaz/phaser-sugar";

interface IProps {
  scene: Phaser.Scene;
  initText: string;
  bgBuilder: (w: number, h: number) => Phaser.GameObjects.NineSlice;
  textBuilder: (text: string) => Phaser.GameObjects.Text;
}

/** Информационные табло - текст и фон **/
export class Info extends Phaser.GameObjects.Container {
  protected text: Phaser.GameObjects.Text;
  protected bg: Phaser.GameObjects.NineSlice;

  constructor(protected props: IProps) {
    super(props.scene);
    this.bg = props.bgBuilder(257, 78);
    this.text = props.textBuilder(props.initText);
    this.layout();
    this.add([this.bg, this.text]);
  }

  isDisabled() {
    return this.scene == null;
  }

  layout() {
    if (this.isDisabled()) return;
    new Align(this.bg).centerY(this.text).leftIn(this.text, 16);
  }

  setText(text: string) {
    if (this.isDisabled()) return;
    this.text.setText(text);
    this.layout();
  }
}
