import { CoreBehavior } from "../../common/game-core";
import { addChildScene } from "../../common/scenes";
import { ViewElementBuilder } from "../../assets";
import { GameEvents, gameStateStore } from "../../logic";

export class SettingsBehavior extends CoreBehavior {
  readonly type = "SettingsBehavior";
  private parentScene: Phaser.Scene | undefined;

  create(parentScene: Phaser.Scene) {
    this.parentScene = parentScene;
    const { childScene, destroy } = addChildScene({ scene: parentScene });
    this.createForChildScene(childScene);
    this.addUnSub(() => destroy());
  }

  private createForChildScene(childScene: Phaser.Scene) {
    const { parentScene } = this;
    if (!parentScene) return;

    const events = new GameEvents(parentScene);
    this.addUnSub(() => events.unSubscribeAll());

    const settings = gameStateStore.getStateConnector("settings");
    const builder = new ViewElementBuilder(childScene);
    const dialog = builder.dialogSettings({
      settings,
      onCloseClick: () => {
        dialog.close();
        events.emit("parentSceneResume");
      },
    });
    dialog.on(Phaser.GameObjects.Events.DESTROY, () => {
      events.emit("parentSceneResume");
    });
    this.addUnSub(dialog);
    events.on("settingsDialogRequested", () => {
      dialog.show();
      events.emit("parentScenePause");
    });
  }
}
