import { CoreGameSessionBehavior } from "../../behaviors/gameSession/CoreGameSessionBehavior";
import { GameSessionTimerBehavior } from "../../behaviors/gameSessionTimer/GameSessionTimerBehavior";
import { SoundSettingsBehavior } from "../../behaviors/soundSettings/SoundSettingsBehavior";
import { SettingsBehavior } from "../../behaviors/settings/SettingsBehavior";
import { KlondikeConsumablesBehavior } from "../../behaviors/consumableBehavior/KlondikeConsumablesBehavior";
import { PauseResumeBehavior } from "../../behaviors/pauseResume/PauseResumeBehavior";
import { CoreBehavior } from "../../common/game-core";
import { onSceneShutdown } from "../../common/scenes";

/** Единый пульт подключения поведений к игровой сцене
 * это кусочки логики + немного обращений к вью
 * они слушают события, перенаправляют их
 * могут открывать диалоги
 * **/
export class GameSceneBehaviors {
  protected behaviors: (undefined | CoreBehavior)[];

  constructor(scene: Phaser.Scene) {
    this.behaviors = [
      CoreGameSessionBehavior.enable(scene, true),
      GameSessionTimerBehavior.enable(scene, true),
      SoundSettingsBehavior.enable(scene, true),
      SettingsBehavior.enable(scene, true),
      KlondikeConsumablesBehavior.enable(scene, true),
      PauseResumeBehavior.enable(scene, true),
    ];

    onSceneShutdown(scene, () => this.destroy());
  }

  destroy() {
    this.behaviors.forEach((behavior) => behavior?.destroy());
  }
}
