import { CoreBehavior } from "../../common/game-core";
import { GameEvents, gameStateStore, IGameSessionState } from "../../logic";
import { shuffleArray, StateConnector } from "../../common";

/**
 *  Ядро запуска игры
 *  без него не стартует пасьянс
 ***/
export class CoreGameSessionBehavior extends CoreBehavior {
  readonly type = "CoreGameSessionBehavior";
  protected events: GameEvents | undefined;
  protected session: StateConnector<IGameSessionState> | undefined;

  create(scene: Phaser.Scene) {
    this.events = new GameEvents(scene);
    this.session = gameStateStore.getStateConnector("gameSession");
    this.addUnSub(() => this.events?.unSubscribeAll());
    this.addUnSub(() => this.session?.unSubScribeAll());

    this.initState({ isNewCards: true });

    /** bind events **/
    this.events.on("onNewGameButtonClick", () => {
      this.initState({ isNewCards: true });
      this.restartSession();
    });
    this.events.on("onReplayGameButtonClick", () => {
      this.initState({ isNewCards: false });
      this.restartSession();
    });

    this.events.on("gameSessionTimerCurrentTimeMs", (timeMs) => {
      this.session?.setState((prev) => ({ ...prev, timeMs }));
    });

    this.events.on("klondikeOnDealFinish", () => {
      this.events?.emit("commandGameSessionTimer", "start");
    });

    /******** START GAME **********/
    this.restartSession();
  }

  private initState({ isNewCards }: { isNewCards?: boolean }) {
    const { session } = this;
    if (!session) {
      console.warn("CoreGameSessionBehavior - session is not initialized");
      return;
    }
    const prevCards = session.getState().deckCards;
    const cards = isNewCards ? shuffleArray(prevCards) : prevCards;
    this.session?.setState({ score: 0, timeMs: 0, deckCards: cards });
  }

  private restartSession() {
    const cards = this.session?.getState().deckCards;
    if (!cards) {
      console.warn("CoreGameSessionBehavior - session is not initialized");
      return;
    }
    this.events?.emit("commandGameSessionTimer", "clear");
    this.events?.emit("gameViewStartKlondike", { cards });
  }
}
