interface IProps {
  gameId: string;
  playerId?: string;
}

interface IDataBase {
  lastTimeUpdate: number;
  lastCloudTimeUpdate: number;
  version: number;
  data: Record<string, object | undefined>;
}

/**
 * Хранит базу в data
 * перед использованием - вызвать preload
 * можно вызывать upload для обновления, но он будет вызыван автоматически при set
 *
 * если set слишком часто - будет откладывать время обновления
 *
 * неучтенные кейсы
 * - сохранение игры в разных вкладках
 **/
export class GameDataService {
  static readonly version = 1;
  private readonly lsKey: string;
  private dataBase: IDataBase;
  private uploadDebounceTimer: ReturnType<typeof setTimeout> | undefined;

  constructor({ gameId, playerId = "defaultHero" }: IProps) {
    this.lsKey = `${gameId}:player-${playerId}:database`;
    this.dataBase = {
      version: GameDataService.version,
      lastTimeUpdate: 0,
      lastCloudTimeUpdate: 0,
      data: {}
    };
  }

  /** Загрузка из локального и/или облачного хранилища */
  async preload(): Promise<void> {
    const { cloudDataBase } = await this.loadDatabaseToCloud();
    const localDataBase = this.getLocalSave();

    const bestFreshSave = this.selectBestVersion([localDataBase, cloudDataBase]);
    if (bestFreshSave) {
      this.dataBase = bestFreshSave;
    }
  }

  /**
   * Загрузить в облако, если прошло достаточно времени
   * иначе заказать загрузку
   * **/
  async upload(): Promise<void> {
    clearTimeout(this.uploadDebounceTimer);
    this.uploadDebounceTimer = undefined;

    const minIntervalSeconds = 10;
    const minIntervalMS = minIntervalSeconds * 1000;
    const timeSinceLastUpdate = Date.now() - this.dataBase.lastCloudTimeUpdate;
    const isUploadAllowed = timeSinceLastUpdate >= minIntervalMS;

    if (!isUploadAllowed) {
      const delay = Math.max(0, minIntervalMS - timeSinceLastUpdate);
      /** вызываем этот же метод отложенным **/
      this.uploadDebounceTimer = setTimeout(() => this.upload().catch(console.warn), delay);
    } else {
      await this.saveDatabaseToCloud();
    }
  }

  /** сохранить в памяти
   * сохранить локально,
   * синхронизировать с облаком
   * если isPartially=true - то можно передавать только часть данных
   * предыдущие значения сохранятся из кэша в памяти
   * **/
  set<T extends object>({ key, data, isPartially = true }: { key: string; data: T; isPartially?: boolean }): void {
    const prevData = this.dataBase.data[key];
    const safeData = typeof prevData === "object" && prevData ? prevData : {};

    this.dataBase.data[key] = isPartially
      ? {
        ...safeData,
        ...data
      }
      : data;

    this.dataBase.lastTimeUpdate = Date.now();

    try {
      this.saveLocalSave();
      this.upload().catch(console.warn);
    } catch (e) {
      console.warn(e);
    }
  }

  /** получить данные по ключе из текущей базы данных в памятие
   * если не найдено - то undefined*/
  get<T extends object>({ key }: { key: string }): T | undefined {
    return this.dataBase.data[key] as T | undefined;
  }

  // ---------- LOCAL STORAGE ----------
  private getLocalSave(): IDataBase | undefined {
    const dataString = localStorage.getItem(this.lsKey);
    if (!dataString) return;

    try {
      return JSON.parse(dataString) as IDataBase;
    } catch (e) {
      console.warn(e);
      console.warn("bad storage data: ", dataString);
      console.warn("bad storage will be deleted now");
      localStorage.removeItem(this.lsKey);
    }
  }

  private saveLocalSave(): void {
    try {
      localStorage.setItem(this.lsKey, JSON.stringify(this.dataBase));
    } catch (e) {
      console.warn(e);
    }
  }

  /*** CLOUD **/
  private async loadDatabaseToCloud(): Promise<{
    isSuccess: boolean;
    cloudDataBase: undefined | IDataBase;
    error?: string;
  }> {
    /**
     * add cloud save here
     * return database from data
     * **/
    return { isSuccess: false, cloudDataBase: undefined, error: "not implemented" };
  }

  private async saveDatabaseToCloud(): Promise<{ isSuccess: boolean; error?: string }> {
    /**
     * add cloud save here
     * this.dataBase must be saved to Cloud
     * только если isSuccess
     * **/

    /** обновлять только в случае успеха **/
    // this.dataBase.lastCloudTimeUpdate = Date.now();
    return { isSuccess: true, error: "not implemented" };
  }

  /*** определение наилучшей версии при загрузке **/
  private selectBestVersion(dataBases: (IDataBase | undefined)[]): IDataBase | undefined {
    const isActualVersion = (base?: IDataBase) => base && base.version === GameDataService.version;
    let bestDataBase = isActualVersion(dataBases[0]) ? dataBases[0] : undefined;

    const isMoreFresh = (base?: IDataBase) => {
      if (base == null) return false;
      if (bestDataBase == null) return true;
      return base.lastTimeUpdate > bestDataBase.lastTimeUpdate;
    };

    for (let i = 1; i < dataBases.length; i++) {
      const nextBase = dataBases[i];
      if (isActualVersion(nextBase) && isMoreFresh(nextBase)) {
        bestDataBase = nextBase;
      } else {
        // migrate case
      }
    }

    return bestDataBase;
  }
}
