import { FontFamily } from "../../../common/game-core";

export function addText(scene: Phaser.Scene, text: string, textStyle?: Phaser.Types.GameObjects.Text.TextStyle) {
  return new Phaser.GameObjects.Text(scene, 0, 0, text, {
    fontFamily: FontFamily.MainBold,
    fontSize: "32px",
    ...textStyle
  });
}
