import { Align } from "@kvisaz/phaser-sugar";
import { ContainerButton } from "../../../../common/game-core";

interface IProps {
  scene: Phaser.Scene;
  name?: string;
  onClick: () => void;
  onHover?: () => void;
  buttonImageBuilder: () => Phaser.GameObjects.Image;
  initAmount?: number;
  textBuilder: (text: string) => Phaser.GameObjects.Text;
  textBgBuilder: (w: number, h: number) => Phaser.GameObjects.NineSlice;
}

/**
 * Универсальная кнопка с указателем какого-то числа amount
 * дизайн по умолчанию - число справа
 **/
export class ConsumableButton extends Phaser.GameObjects.Container {
  private readonly textBg: Phaser.GameObjects.NineSlice;
  private readonly text: Phaser.GameObjects.Text;
  private readonly button: ContainerButton;
  private readonly align = new Align();
  private amount = 0;

  constructor(private props: IProps) {
    super(props.scene);
    this.name = props.name ?? "consumableButton";
    this.amount = this.props.initAmount ?? 0;
    const scale = 0.89;
    const textBg = props.textBgBuilder(90, 68);
    const text = props.textBuilder(`${this.amount}`);
    const image = props.buttonImageBuilder();

    const button = new ContainerButton({
      gameObjects: [image],
      onClick: this.props.onClick,
      onOver: () => {
        this.props.onHover?.();
      },
      options: {
        once: false,
        onDisabled: () => {
          image.setTint(0xa0a0a0);
          this.updateEnableText();
        },
        onEnabled: () => {
          image.clearTint();
          this.updateEnableText();
        },
        disableAfterClick: {
          ms: 0,
        },
      },
    });
    button.setScale(scale);

    this.add([textBg, text, button]);
    this.scene.add.existing(this);

    this.textBg = textBg;
    this.text = text;
    this.button = button;

    this.layout();
  }

  layout() {
    const { align, textBg, button, text } = this;

    const textBgWidth = 60 + text.width;
    textBg.width = textBgWidth;
    align.anchor(button).centerY(textBg).rightTo(textBg, -32);
    align.anchor(button).centerY(text).rightTo(text, 8);

    console.log("this.amount = 0", this.amount);
    console.log("this.button.isEnabled", this.button.isEnabled);

    /** !!!!! Никогда не блокируй то !!!!!
     * что можно использовать
     * для продажи и показа рекламы
     **/
    /*if (this.amount == 0 && this.button.isEnabled) {
      console.log("disable!");
      this.enable(false);
    }

    if (this.amount > 0 && !this.button.isEnabled) {
      console.log("enable!");
      this.enable(true);
    }*/
  }

  setAmount(amount: number) {
    if (this.scene == null) return;
    this.amount = Math.max(0, amount);
    this.text.setText(`${this.amount}`);
    this.layout();
  }

  enable(enabled = true) {
    this.button.enable(enabled);
  }

  private updateEnableText() {
    const alpha = this.button.isEnabled ? 1 : 0.35;
    this.textBg.setAlpha(alpha);
    this.text.setAlpha(alpha);
  }
}
