/** расширяем из логики **/
export type Locale = 'ru' | 'en';

export enum SettingType {
  isMusicOn='isMusicOn',
  isSoundOn='isSoundOn',
  locale='locale'
}

export type SettingChange =
  | { key: SettingType.isMusicOn, value: boolean }
  | { key: SettingType.isSoundOn, value: boolean }
  | { key: SettingType.locale, value: Locale }

export interface ISettingsState {
  isMusicOn: boolean;
  isSoundOn: boolean;
  locale: Locale;
}
