import { deepCopy, getCardClassic52Deck, State, StateConnector } from "../../common";
import { MemoryStorage, MemoryStorageProvider } from "../../common/game-core";
import { GameStateRecord, IStateStoreData, StateValue } from "./types";
import { IPlayerGoodyState, ISettingsState } from "../models";
import { IGameSessionState } from "../models/gameSession";

class GameStateStore {
  private states: GameStateRecord = {
    settings: new State<ISettingsState>({
      isSoundOn: true,
      isMusicOn: true,
      locale: "en",
    }),
    playerGoodyState: new State<IPlayerGoodyState>({
      undoAmount: 3,
      hintAmount: 3,
      visionAmount: 3,
      magicAmount: 3,
    }),
    gameSession: new State<IGameSessionState>({
      score: 0,
      timeMs: 0,
      deckCards: getCardClassic52Deck().cards.all
    }),
  };

  private static memoryStorageKey = "gameStateRegistry";

  constructor(
    private props: {
      memoryStorage: MemoryStorage;
    },
  ) {
    this.loadFromStorage();
    this.initAutoSave();
  }

  loadFromStorage() {
    const savedData = this.props.memoryStorage.get<IStateStoreData>(
      GameStateStore.memoryStorageKey,
    );
    if (!savedData) return;

    this.forEachState((key, state) => {
      const savedValue = savedData[key as keyof IStateStoreData];
      if (savedValue != null) {
        state.setState(savedValue as never);
      }
    });
  }

  /**
   *  коннектор состояния - для хранения подписок в конкретном случае
   *  - можно вызывать unSubscribeAll для очистки конкретного компонента или случая
   *  без влияния на остальных подписчиков стейта
   *  - подключается к тому же эмиттеру
   */
  getStateConnector<K extends keyof GameStateRecord>(
    key: K,
  ): StateConnector<StateValue<GameStateRecord[K]>> {
    const state = this.states[key];
    return new StateConnector(state as unknown as State<StateValue<GameStateRecord[K]>>);
  }

  /** как итерировать и отписаться от всех **/
  unSubscribeAll() {
    this.forEachState((_, state) => state.unSubScribeAll());
  }

  private forEachState(callback: (key: keyof GameStateRecord, state: State<unknown>) => void) {
    (Object.keys(this.states) as Array<keyof GameStateRecord>).forEach((key) => {
      callback(key, this.states[key] as State<unknown>);
    });
  }

  private mapStates<R>(
    mapper: (key: keyof GameStateRecord, state: State<unknown>) => R,
  ): Record<string, R> {
    return (Object.keys(this.states) as Array<keyof GameStateRecord>).reduce<Record<string, R>>(
      (acc, key) => {
        acc[key as string] = mapper(key, this.states[key] as State<unknown>);
        return acc;
      },
      {},
    );
  }

  saveToStorage() {
    const snapshot = this.mapStates((_, state) => state.getState());
    this.props.memoryStorage.set(
      GameStateStore.memoryStorageKey,
      snapshot as unknown as IStateStoreData,
    );
  }

  private initAutoSave() {
    this.forEachState((_, state) => {
      state.on(() => this.saveToStorage());
    });
  }
}

/** Доступ к отдельным живым стейтам @State через коннекторы **/
export const gameStateStore = new GameStateStore({
  memoryStorage: MemoryStorageProvider.getStorage(),
});
