import { getCurrentLocale, ViewElementBuilder } from "../../../assets";
import { Align, cssColorToInt } from "@kvisaz/phaser-sugar";
import { addBackButton } from "../utils";
import { resetSearchParam } from "../../../common";
import { FontFamily, Scenes } from "../../../common/game-core";

export class KlondikedViewTestScene extends Phaser.Scene {
  preload() {}

  create() {
    const scene = this;
    const builder = new ViewElementBuilder(scene);
    builder.backgroundGameScene();
    const locale = getCurrentLocale();
    const align = new Align();

    const simpleTextBuilder = (str: string = "", bounds: { width?: number; height?: number } = {}) => {
      const text = new Phaser.GameObjects.Text(scene, 0, 0, str, {
        fontFamily: FontFamily.MainBold,
        color: "#dedede",
        fontSize: `${24}px`,
        align: "center",
      });
      const rectangle = new Phaser.GameObjects.Rectangle(
        scene,
        0,
        0,
        bounds.width ?? 150,
        bounds.height ?? 200,
        cssColorToInt("#7a7851"),
        0.5,
      );
      rectangle.setStrokeStyle(2, cssColorToInt("#7a7851"));

      new Align(rectangle).center(text);
      const container = new Phaser.GameObjects.Container(scene, 0, 0, [rectangle, text]);

      scene.add.existing(container);
      const { width, height } = container.getBounds();
      container.setSize(width, height);
      return container;
    };

    /** fieldMargins **/
    const fieldMargin = { left: 16, right: 16, top: 58, bottom: 16 };
    const fieldBounds = new Phaser.GameObjects.Rectangle(
      scene,
      fieldMargin.left,
      fieldMargin.top,
      scene.sys.canvas.width - fieldMargin.left - fieldMargin.right,
      scene.sys.canvas.height - fieldMargin.top - fieldMargin.bottom,
      cssColorToInt("#dedede"),
      0,
    ).setOrigin(0, 0);
    scene.add.existing(fieldBounds);

    /** размеры зон для карточки **/
    const zoneBounds = { width: 150, height: 200 };

    /** backCover button **/
    const backButton = addBackButton({
      scene: this,
      onClick: () => {
        resetSearchParam("test");
        scene.scene.start(Scenes.TestScene);
      },
    });
  }
}
