import { CoreBehavior } from "../../common/game-core";
import { GameEvents } from "../../logic";

export class PauseResumeBehavior extends CoreBehavior {
  create(scene: Phaser.Scene) {
    const gameEvents = new GameEvents(scene);
    this.addUnSub(() => {
      gameEvents.unSubscribeAll();
    });

    gameEvents.on("parentScenePause", () => {
      scene.scene.pause(scene.scene.key);
    });

    gameEvents.on("parentSceneResume", () => {
      scene.scene.resume(scene.scene.key);
    });
  }
}
